    correctKey: 'A',
    explanation: '河川法第26条により、河川区域内において工作物の新築・改築・除却を行う場合は河川管理者の許可が必要である。また第27条により、土地の掘削・盛土・切土その他土地の形状を変更する行為や土石の採取も許可を要し、届出で足りるわけではない。河川管理者は、一級河川が国土交通大臣（指定区間は都道府県知事に管理を委任）、二級河川が都道府県知事、準用河川が市町村長である。河川保全区域は河川区域に隣接して堤防等を保護するために指定される別区域で、原則として河川区域の境界から50メートルを超えない範囲で指定される。\\n\\n【図解】河川の種別と河川管理者\\n　種別｜河川管理者｜補足\\n　一級河川｜国土交通大臣｜指定区間は都道府県知事が管理\\n　二級河川｜都道府県知事｜一級水系以外の重要な河川\\n　準用河川｜市町村長｜二級河川の規定を準用する\\n　⇒ 河川区域内の工作物設置も土石採取も、いずれも許可が必要\\n　⚠ 一級を都道府県知事、二級を国土交通大臣とする入れ替えが定番のひっかけ。',
