    explanation: '土量の変化率は地山土量を基準として表す。ほぐし率Lはほぐした土量を地山土量で除した値で、掘削により土がほぐれて体積が増えるため一般に1.0より大きく、砂で1.10〜1.20、岩塊では1.40〜1.75程度となる。締固め率Cは締め固めた土量を地山土量で除した値で、締固めにより間隙が減って体積が縮むため一般に1.0より小さく、0.85〜0.95程度である。変化率は土質により異なるため一定値ではなく、運搬計画や土量配分計画では地山・ほぐし・締固めの各状態の土量を明確に区別して算定する必要がある。\\n\\n【図解】土量の状態と変化率\\n　状態｜地山土量との関係｜一般的な値\\n　地山土量｜変化率の基準となる状態｜1.00\\n　ほぐし土量｜地山土量にLを乗じる｜Lは1.0より大きい\\n　締固め土量｜地山土量にCを乗じる｜Cは1.0より小さい\\n　⇒ 掘削すると膨張してLは1超、締め固めると収縮してCは1未満\\n　⚠ LとCの大小関係を入れ替える出題が定番。Lが1超、Cが1未満と覚える。',
