    correctKey: 'C',
    explanation: '擁壁の設計では、背面土からの土圧として主として主働土圧が用いられる。主働土圧は壁体が土から離れる方向にわずかに変位する際に生じる最小の土圧であり、擁壁設計における標準的な設計外力である。受働土圧は逆に壁体が土を押し込む方向に変位する際に生じる最大の抵抗力であり、擁壁前面の受働抵抗として限定的に考慮されることはあるが設計の主体とはならない。安定計算は転倒・滑動・支持力の3項目を照査し、転倒は合力の作用位置が底版中央の3分の1以内に収まることを確認する。背面には水抜き孔と透水層を設け、水圧の上昇を防ぐ。\\n\\n【図解】擁壁の安定照査3項目\\n　照査項目｜検討する内容｜代表的な判定基準\\n　転倒｜合力の作用位置｜底版中央の3分の1以内\\n　滑動｜底面のせん断抵抗｜所要の安全率を確保\\n　支持力｜底面反力と地盤の支持力｜許容支持力以下\\n　⇒ 設計土圧は主働土圧、受働土圧は前面抵抗として限定的に考慮\\n　⚠ 「常に受働土圧を用いる」は誤り。主働土圧と受働土圧の役割の取り違えが頻出。',
    difficulty: 'advanced',
