    explanation: '盛土内部への浸透水の滞留は、間隙水圧の上昇と土のせん断強度の低下を招き、盛土のすべり破壊や法面崩壊の主要な原因となるため、排水対策は不可欠である。排水工は目的別に、法肩排水溝・小段排水溝・縦排水溝などの地表水排水工と、暗渠排水・水平排水層・地下排水溝などの地下水排水工に大別される。地表水排水工は表面水を速やかに集水・排除して浸食を防ぎ、地下水排水工は盛土内や切土背面に浸透した水を排除して間隙水圧の上昇を抑える。施工中の仮排水計画も、掘削箇所への雨水流入と滞水を防ぐうえで欠かせない。\\n\\n【図解】排水工の種類と目的\\n　区分｜代表的な施設｜主なねらい\\n　地表水排水工｜法肩排水溝・縦排水溝｜表面水の集排水と浸食の防止\\n　地下水排水工｜暗渠排水・水平排水層｜間隙水圧の上昇抑制\\n　仮排水工｜釜場・排水ポンプ｜施工中の滞水防止と安全確保\\n　⇒ 水は盛土の安定性を低下させる方向にしか働かない\\n　⚠ 「浸透水が滞留すると安定性が向上するので排水は不要」は完全な逆で誤り。',
    difficulty: 'basic',
