    explanation: '実積率は、容器に詰めた骨材の絶対容積が容器の全容積に占める割合を百分率で示す指標であり、値が大きいほど骨材が密実に詰まっており、骨材間の空隙率は逆に小さいことを意味する。実積率の高い骨材を用いると、同じワーカビリティーを得るのに必要なセメントペースト量が少なくて済み、単位水量と単位セメント量を減らせるため経済的で乾燥収縮も小さくなる。粗粒率FMは各標準ふるいの累積残留百分率の合計を100で除した値で、大きいほど粒度が粗いことを示す。混和材の効果とあわせて整理しておきたい。\\n\\n【図解】骨材と混和材の指標・効果\\n　項目｜値が大きい、または用いると｜実務上の意味\\n　実積率｜骨材が密で空隙が少ない｜単位水量とセメント量を減らせる\\n　粗粒率FM｜粒度が粗い｜骨材の粗さを表す基本指標\\n　フライアッシュ｜ワーカビリティーが改善する｜水和熱の抑制と長期強度の増進\\n　高炉スラグ微粉末｜長期強度が増進する｜塩分浸透抵抗性と化学抵抗性の向上\\n　⇒ 実積率が大きいほど空隙は少ない、という向きを間違えない\\n　⚠ 「実積率が大きいほど骨材間の空隙が多い」は大小関係が逆で誤り。',
