    question: 'レディーミクストコンクリートの運搬及び荷卸しに関する記述のうち、不適当なものはどれか。',
    choices: [
      { key: 'A', text: '練混ぜから打込み終了までの時間は、外気温が25℃を超える場合は1.5時間以内、25℃以下の場合は2時間以内を標準とする。', explanation: '正しい。気温に応じた練混ぜから打込みまでの時間の標準的な管理値である。' },
      { key: 'B', text: 'アジテータ車による運搬では、荷卸し直前にドラムを高速回転させて材料分離を促進させることが望ましい。', explanation: '誤り。荷卸し前の高速攪拌は材料を均一化するために行うものであり、材料分離を促進する操作ではない。' },
      { key: 'C', text: '荷卸し地点でスランプが規格値を満たさない場合、加水によりスランプを調整することは、水セメント比の増大を招くため認められない。', explanation: '正しい。荷卸し後の加水は水セメント比を増大させ強度・耐久性を低下させるため認められない。' },
      { key: 'D', text: '運搬時間が長くなるとスランプの経時低下が生じるため、練混ぜ時間や運搬計画を適切に管理する必要がある。', explanation: '正しい。運搬時間が長いほどスランプロスが生じやすく、運搬計画の管理が重要である。' },
    ],
    correctKey: 'B',
    explanation: 'アジテータ車での運搬は、コンクリートの材料分離を防止し均一な品質を保つために行うものであり、荷卸し直前の高速攪拌は「材料の均一化」を目的とするのであって「材料分離の促進」ではない。分離を促進させるような操作は品質低下につながり誤りである。練混ぜから打込み終了までの時間は気温に応じ25℃超で1.5時間以内、25℃以下で2時間以内とするのが標準であり、スランプ不足時の加水は水セメント比を増大させるため認められていない。\n【図解】運搬・荷卸し管理の要点\n○練混ぜ〜打込み：25℃超1.5時間以内／25℃以下2時間以内\n○運搬時間管理はスランプの経時低下対策として重要\n×荷卸し前の攪拌は材料分離の促進ではなく均一化が目的\n→スランプ不足時の加水は水セメント比増大を招くため不可\n⚠現場での安易な加水は絶対に行ってはならない★',
