    explanation: '鋼管杭の防食は、大気中・飛沫帯・海中部・土中部など環境条件（腐食速度）が部位により大きく異なるため、それぞれの腐食環境に応じた仕様（腐食代の設定、塗装仕様、電気防食の適用範囲等）を使い分けて設計するのが基本である。特に飛沫帯・干満帯は最も腐食が進行しやすい部位として重点的な対策が必要であり、「全ての範囲で同一仕様」とする記述は誤りである。\n【図解】鋼管杭の防食対策\n○腐食代の設計上の見込み、電気防食（犠牲陽極方式等）が有効\n○土中部の腐食速度は大気中・海水中より一般に小さい\n×全範囲で同一塗装仕様とするのは誤り（部位別に使い分ける）\n→飛沫帯・干満帯は特に腐食が進行しやすく重点対策が必要\n⚠腐食環境の厳しさに応じた仕様の使い分けが不可欠★',
    difficulty: 'standard',
