    question: '盛土のり面の安定計算（円弧すべり法）に関する記述のうち、適当なものはどれか。',
    choices: [
      { key: 'A', text: '円弧すべり法は、想定したすべり面を円弧と仮定し、すべり面上の抵抗力（せん断強度）とすべろうとする力（滑動力）の比である安全率を算定する手法である。', explanation: '正しい。抵抗モーメントと滑動モーメントの比として安全率を算定する手法である。' },
      { key: 'B', text: '安全率が1.0を下回る場合、そのすべり面は安定していると判断される。', explanation: '誤り。安全率が1.0を下回る場合は、そのすべり面が不安定であると判断される。' },
      { key: 'C', text: '分割法（スライス法）では、すべり土塊をいくつかのスライスに分割して計算するが、スライス間に作用する力はいかなる計算方法でも一切考慮しない。', explanation: '誤り。スライス間力を無視する簡便法（フェレニウス法）と、スライス間力を考慮する精算法（ビショップ法等）があり、方法により扱いが異なる。' },
      { key: 'D', text: '盛土のり面の安全率は、盛土の含水状態にかかわらず常に一定の値となる。', explanation: '誤り。降雨等により含水状態が変化するとせん断強度が低下し、安全率も変化する。' },
    ],
    correctKey: 'A',
    explanation: '円弧すべり法（分割法・スライス法）は、想定したすべり面を円弧と仮定し、すべり面に沿う抵抗力（せん断強度による抵抗モーメント）とすべろうとする力（自重等による滑動モーメント）の比を安全率として算定し、最も危険なすべり面を検討する手法である。安全率が1.0を下回るとそのすべり面は不安定と判断される。分割法にはスライス間力を無視する簡便法（フェレニウス法）とスライス間力を考慮する精算法（ビショップ法等）があり、精度に差がある。\n【図解】円弧すべり安定計算の基本\n○安全率＝抵抗モーメント／滑動モーメントで算定\n○降雨等による含水状態の変化は安全率を低下させる要因\n×安全率1.0未満で安定と判断するのは誤り（実際は不安定）\n→簡便法と精算法でスライス間力の扱いが異なる\n⚠含水状態の変化を軽視すると重大な安定性評価誤りにつながる★',
