    choices: [
      { key: 'A', text: 'セメント安定処理は、現地土やセメントを混合し、化学的な固結作用により路床・路盤の支持力を向上させる工法である。', explanation: '正しい。セメント安定処理はセメントの水和反応による固結作用を利用し、現地土の強度・支持力を改良する工法である。' },
      { key: 'B', text: '石灰安定処理は、主に高含水比の粘性土に適用され、含水比低下や強度増加の効果が期待できる。', explanation: '正しい。石灰安定処理は消化・化学反応の発熱による含水比の低下と、ポゾラン反応による長期的な強度増加の効果があり、粘性土の改良に適している。' },
      { key: 'C', text: '安定処理路盤は、一般に無処理の路盤に比べて支持力（CBR等）が低下する。', explanation: '誤り。安定処理はセメントや石灰の添加により土の強度・支持力を「向上」させる工法であり、無処理の路盤に比べて支持力（CBR等）は増加する。' },
      { key: 'D', text: '安定処理材の散布・混合にあたっては、均一な品質を確保するため、所定の散布量・混合深さを管理する必要がある。', explanation: '正しい。安定処理の効果を確実に発揮させるためには、安定材の散布量・混合深さ・含水比等を適切に管理することが重要である。' },
    ],
    correctKey: 'C',
    explanation: '安定処理工法は、現地の土質材料にセメントや石灰等の安定材を添加・混合することで、化学的な固結作用により支持力（CBR）や強度を向上させる目的で行われる工法であり、支持力が低下することはない。セメント安定処理はセメントの水和反応による固結を利用し、砂質土を中心に幅広い土質に適用でき早期に強度が発現する。石灰安定処理は生石灰の消化に伴う発熱と吸水による含水比の低下と、その後のポゾラン反応による長期的な強度増加が特徴で、高含水比の粘性土に適する。施工では散布量・混合深さ・含水比の管理が品質を左右する。\\n\\n【図解】安定処理材の使い分け\\n　安定材｜適する土質｜主な効果\\n　セメント｜砂質土を中心に幅広い土質｜水和反応による早期の強度発現\\n　生石灰｜高含水比の粘性土｜消化熱と吸水による含水比低下\\n　消石灰｜粘性土｜ポゾラン反応による長期強度の増加\\n　⇒ 安定処理の目的は支持力の向上であり、低下ではない\\n　⚠ 「安定処理路盤は無処理の路盤より支持力が低下する」は工法の目的と正反対で誤り。',
    difficulty: 'basic',
