    question: '鉄道の営業線近接工事に関する記述のうち、適当なものはどれか。',
    choices: [
      { key: 'A', text: '建築限界とは、車両の走行に必要な最小限の空間であり、これを侵す構造物や作業員の立入りは禁止される。', explanation: '正しい。建築限界は車両の安全な走行を確保するために設けられた空間であり、この範囲内への支障は認められない。' },
      { key: 'B', text: '線路閉鎖工事とは、列車の運行を継続したまま、軌道上で直接作業を行う工事のことをいう。', explanation: '誤り。線路閉鎖工事は、列車の運行を「中止」し、当該区間への列車の進入を遮断したうえで安全に作業を行う工事のことをいう。列車運行を継続したまま行う工事とは異なる。' },
      { key: 'C', text: '営業線近接工事において、工事管理者の配置は工事の規模にかかわらず一切不要である。', explanation: '誤り。営業線近接工事では、列車運行の安全確保のため、工事の内容・規模に応じて工事管理者や列車見張員の配置が必要となる。' },
      { key: 'D', text: '軌道保守用車両（マルチプルタイタンパ等）は、一般車両と同一の運転資格・取扱いで運用できる。', explanation: '誤り。軌道保守用車両は専用の資格・取扱い基準に基づき運用される特殊車両であり、一般車両と同一の運転資格で扱えるものではない。' },
    ],
    correctKey: 'A',
    explanation: '建築限界は、鉄道車両が安全に走行するために線路上に確保すべき空間の限界であり、この範囲内に構造物や作業員・機材等が支障することは、列車の安全運行を脅かすため厳格に禁止されている。建築限界は車両限界の外側に余裕を持たせて定められ、曲線区間では車両の偏いに応じて拡大される。営業線近接工事では、建築限界の遵守に加え、工事管理者・線閉責任者・列車見張員の配置、列車の進入を遮断して作業する線路閉鎖工事やき電停止など、作業内容に応じた厳格な保安体制のもとで施工する必要がある。\\n\\n【図解】営業線近接工事の保安の要点\\n　項目｜内容｜ねらい\\n　建築限界｜車両限界の外側に定めた空間｜支障物の侵入を許さない\\n　線路閉鎖工事｜列車の進入を遮断して作業する｜作業中の列車接触の防止\\n　工事管理者と見張員｜工事内容と規模に応じて配置｜異常時の退避と合図\\n　⇒ 建築限界を侵す作業は規模の大小を問わず認められない\\n　⚠ 線路閉鎖工事を「列車の運行を継続したまま軌道上で作業する工事」とするのは定義が逆で誤り。',
