    subjectName: '専門土木',
    question: '土木構造物の耐震設計・耐震対策に関する記述のうち、適当なものはどれか。',
    choices: [
      { key: 'A', text: 'レベル1地震動は、供用期間中に発生する確率が高い、比較的発生頻度の高い地震動として設定される。', explanation: '正しい。レベル1地震動は供用期間中に発生する可能性の高い中規模の地震動であり、構造物は原則として無被害または軽微な被害にとどまることが求められる。' },
      { key: 'B', text: 'レベル2地震動は、レベル1地震動よりも発生頻度が高く、供用期間中に必ず発生する地震動として設定される。', explanation: '誤り。レベル2地震動は、発生頻度は低いものの、発生すれば甚大な被害をもたらす可能性のある「最大級」の地震動として設定されるものであり、レベル1地震動より発生頻度が高いわけではない。' },
      { key: 'C', text: '免震構造は、構造物の固有周期を短くすることで、地震力そのものを構造物に伝わりにくくする耐震技術である。', explanation: '誤り。免震構造は免震装置（積層ゴム等）により構造物の固有周期を「長く」（長周期化）し、地震動の卓越周期とずらすことで応答を低減する技術である。固有周期を短くするという記述は逆である。' },
      { key: 'D', text: '液状化のおそれがある地盤上の構造物では、耐震設計にあたって液状化の影響を考慮する必要はない。', explanation: '誤り。液状化のおそれがある地盤では、地盤の支持力喪失や側方流動が構造物に重大な影響を及ぼすため、耐震設計において液状化の影響を適切に考慮する必要がある。' },
    ],
    correctKey: 'A',
    explanation: 'レベル1地震動は構造物の供用期間中に発生する可能性が高い中規模の地震動、レベル2地震動は発生頻度は低いものの発生すれば甚大な被害をもたらしうる最大級の地震動として、それぞれ耐震設計の基本方針に位置付けられている。レベル1に対しては原則として無被害または軽微な損傷、レベル2に対しては構造物の重要度に応じて損傷を限定し致命的な被害を避けることが求められる。免震構造は積層ゴム等により固有周期を長周期化し、地震動の卓越周期とずらすことで応答を低減する技術であり、固有周期を短くするものではない。\\n\\n【図解】設計地震動のレベルと要求性能\\n　区分｜発生頻度｜求められる性能\\n　レベル1地震動｜供用期間中に発生の可能性が高い｜無被害または軽微な損傷\\n　レベル2地震動｜発生頻度は低いが最大級｜致命的な被害を避ける\\n　⇒ 免震は固有周期を長くして地震応答を小さくする技術\\n　⚠ レベル1とレベル2の発生頻度を入れ替える出題が定番。頻度が高いのはレベル1である。',
