    explanation: '労働災害は、設備の欠陥や作業環境の不備といった不安全な状態と、作業員の不注意や手順違反といった不安全な行動の両方が複合的に関与して発生することが多いため、防止対策も両面から講じる必要がある。ヒヤリ・ハット活動は災害には至らなかった事例を幅広く収集・分析して重大災害を未然に防ぐ活動、KYK（危険予知活動）は作業前に当日の危険要因を洗い出して共有する活動であり、いずれも日常的な安全活動として重要な役割を果たす。災害統計では度数率と強度率が代表的な指標として用いられる。\\n\\n【図解】労働災害の統計指標\\n　指標｜分母となる量｜表しているもの\\n　度数率｜100万延べ実労働時間｜災害の発生頻度\\n　強度率｜1000延べ実労働時間｜災害の重さ（労働損失日数）\\n　年千人率｜1年間の平均労働者数1000人｜1年あたりの被災率\\n　⇒ 対策は不安全な状態と不安全な行動の両面から講じる\\n　⚠ ヒヤリ・ハット活動を「重大な労働災害の事例のみを収集する活動」とするのは対象の取り違えで誤り。',
