    question: '施工体制台帳・施工体系図に関する記述のうち、適当なものはどれか。',
    choices: [
      { key: 'A', text: '施工体制台帳は、下請契約を締結する場合、その金額にかかわらず、特定建設業者は常に作成する必要がある。', explanation: '誤り。施工体制台帳の作成義務は、発注者から直接請け負った特定建設業者が、下請契約の総額が政令で定める金額以上となる場合に生じるものであり、金額にかかわらず「常に」作成義務が生じるわけではない。' },
      { key: 'B', text: '施工体制台帳には、下請負人の名称、工事内容、技術者の氏名等を記載する。', explanation: '正しい。施工体制台帳には、各下請負人の名称・請け負った工事の内容・配置技術者の氏名等、施工体制を把握するために必要な事項を記載する。' },
      { key: 'C', text: '施工体系図は、工事関係者の見やすい場所に掲示する必要はなく、発注者にのみ提出すればよい。', explanation: '誤り。施工体系図は、当該工事に従事するすべての関係者が施工体制を把握できるよう、工事現場の見やすい場所に掲示することが義務付けられている。' },
      { key: 'D', text: '施工体制台帳の作成義務は、公共工事に限定され、民間工事には適用されない。', explanation: '誤り。施工体制台帳の作成義務は建設業法に基づく規定であり、公共工事に限らず、要件を満たす民間工事にも適用される。' },
    ],
