    explanation: '施工体制台帳は、発注者から直接工事を請け負った特定建設業者が、下請契約の総額が4500万円（建築一式工事は7000万円）以上となる場合に作成が義務付けられるもので、各下請負人の名称・請け負った工事の内容・配置技術者の氏名等を記載し、工事現場に備え置く。あわせて作成する施工体系図は下請負人の施工分担関係を樹形図で示したもので、工事関係者が見やすい場所に掲示しなければならない。この義務は建設業法に基づくものであり、公共工事に限らず要件を満たす民間工事にも適用される点に注意する。\\n\\n【図解】施工体制台帳と施工体系図\\n　項目｜施工体制台帳｜施工体系図\\n　作成義務者｜元請の特定建設業者｜元請の特定建設業者\\n　主な内容｜下請名・工事内容・技術者名｜下請の施工分担関係の樹形図\\n　取扱い｜現場に備え置き閲覧に供する｜見やすい場所に掲示する\\n　⇒ 下請総額4500万円以上（建築一式は7000万円以上）が作成義務の目安\\n　⚠ 「公共工事にのみ適用」「金額にかかわらず常に作成義務」はいずれも誤り。',
