    choices: [
      { key: 'A', text: '特定建設資材とは、コンクリート、コンクリート及び鉄からなる建設資材、木材、アスファルト・コンクリートの4種類が指定されている。', explanation: '正しい。建設リサイクル法における特定建設資材は、コンクリート・コンクリート及び鉄からなる建設資材・木材・アスファルト・コンクリートの4品目である。' },
      { key: 'B', text: '対象建設工事に該当する場合であっても、分別解体・再資源化等の実施は任意であり、義務ではない。', explanation: '誤り。建設リサイクル法における対象建設工事（一定規模以上の解体工事・新築工事等）に該当する場合、分別解体・再資源化等の実施は法律上の「義務」であり、任意ではない。' },
      { key: 'C', text: '対象建設工事の発注者・受注者は、工事着手の7日前までに、都道府県知事等へ届出を行う必要がある。', explanation: '誤り。届出は「発注者」が工事着手の7日前までに行う必要がある（受注者ではなく発注者が届出義務者である点に注意）。' },
      { key: 'D', text: '木材の再資源化は、破砕等を行わずそのまま原形のまま再使用することのみが認められており、チップ化や縮減による処理は一切認められない。', explanation: '誤り。木材の再資源化は破砕等によりチップ化を行うのが基本であり、再資源化が技術的・経済的に困難な場合には縮減（焼却等）による処理も認められている。原形のままの再使用のみに限定されるものではない。' },
    ],
    correctKey: 'A',
    explanation: '建設リサイクル法における特定建設資材は、コンクリート、コンクリート及び鉄からなる建設資材、木材、アスファルト・コンクリートの4品目に限定されている。一定規模以上の対象建設工事に該当する場合、分別解体等と再資源化等の実施は法律上の義務であり任意ではない。届出は発注者が工事着手の7日前までに都道府県知事等に対して行う必要があり、受注者ではない点が頻出の論点である。木材の再資源化はチップ化が基本で、再資源化が技術的・経済的に困難な場合には縮減による処理も認められている。\\n\\n【図解】建設リサイクル法の対象建設工事の規模\\n　工事の種類｜規模の基準｜届出の期限\\n　建築物の解体｜床面積80平方メートル以上｜着手の7日前まで\\n　建築物の新築・増築｜床面積500平方メートル以上｜着手の7日前まで\\n　建築物の修繕・模様替｜請負代金1億円以上｜着手の7日前まで\\n　その他の工作物の工事｜請負代金500万円以上｜着手の7日前まで\\n　⇒ 特定建設資材はコンクリート、コンクリートと鉄、木材、アスファルトコンクリートの4品目\\n　⚠ 届出義務者を受注者とするのは誤り。届出を行うのは発注者である。',
