    question: '品質管理におけるPDCAサイクルに関する記述のうち、不適当なものはどれか。',
    choices: [
      { key: 'A', text: 'PDCAサイクルは、Plan（計画）、Do（実施）、Check（確認・評価）、Action（処置・改善）の4段階を繰り返すことで、継続的な品質向上を図る管理手法である。', explanation: '正しい。4段階を繰り返す継続的改善の手法である。' },
      { key: 'B', text: 'Check（確認・評価）の段階では、計画と実施結果の差異を分析し、問題点を明らかにする。', explanation: '正しい。差異分析により問題点を明らかにするのがCheck段階の役割である。' },
      { key: 'C', text: 'Action（処置・改善）の段階で得られた知見は、次のPlan（計画）段階には反映させず、独立した改善活動として完結させる。', explanation: '誤り。Actionで得られた知見は次のPlanに反映させ、循環的に改善を図るのがPDCAの本質である。' },
      { key: 'D', text: 'PDCAサイクルは、施工計画・品質管理・原価管理など、建設工事の様々な管理活動に応用できる考え方である。', explanation: '正しい。PDCAは幅広い管理活動に応用できる考え方である。' },
    ],
    correctKey: 'C',
    explanation: 'PDCAサイクルは、Plan（計画）→Do（実施）→Check（確認・評価）→Action（処置・改善）の4段階を繰り返す継続的改善の手法であり、Action段階で得られた知見・改善策は次のPlan段階に反映させることでスパイラルアップ的に品質を向上させる点が本質である。「独立した改善活動として完結させる」という記述は、PDCAサイクルの循環構造を否定するものであり誤りである。\n【図解】PDCAサイクルの循環構造\n○Plan→Do→Check→Actionの4段階を繰り返す\n○Checkでは計画と実施結果の差異を分析する\n×Actionの結果を次のPlanに反映させない、は誤り\n→施工計画・品質管理・原価管理等、幅広く応用できる\n⚠PDCAは一度きりでなく継続的に循環させることが本質★',
