    correctKey: 'B',
    explanation: 'レディーミクストコンクリートの受入検査では、スランプ、空気量、塩化物含有量、強度等について規定の許容差・基準値内であるかを確認する。空気量の目標値は普通コンクリート約4.5%、軽量コンクリート約5.0%等、コンクリートの種類により異なり、許容差もこれに応じて運用される。塩化物含有量は鋼材腐食防止の観点から原則0.30kg/m³以下と定められている。受入検査に不合格となったコンクリートは荷卸しせず返送する等の措置が必要である。\n【図解】受入検査の主要項目\n○スランプ許容差は指定スランプの値により異なる\n○塩化物含有量は原則0.30kg/m³以下が上限\n×空気量の目標値がコンクリート種類にかかわらず一律、は誤り\n→不合格コンクリートは荷卸しせず返送等の措置を実施\n⚠受入検査基準の理解不足は品質事故に直結する★',
