    question: '公共工事の入札及び契約の適正化の促進に関する法律（入契法）に関する記述のうち、不適当なものはどれか。',
    choices: [
      { key: 'A', text: '公共工事の発注者は、毎年度、当該年度に発注を予定する公共工事の発注見通しを公表しなければならない。', explanation: '正しい。発注者には、年度当初等に発注見通しを公表する義務が課されている。' },
      { key: 'B', text: '発注見通しの公表は義務ではなく、発注者の任意の判断に委ねられている。', explanation: '誤り。入契法において、発注見通しの公表は発注者に課された法律上の義務であり、任意の判断に委ねられているものではない。' },
      { key: 'C', text: '公共工事の入札及び契約の適正化を図るため、発注者には施工体制台帳の写しの提出を求める等の措置が定められている。', explanation: '正しい。入契法に基づき、発注者は施工体制の適正化のため施工体制台帳の写しの提出等を求めることができる。' },
      { key: 'D', text: '入契法は、一括下請負（丸投げ）の禁止の徹底など、建設業の適正な施工体制の確保を図ることを目的の一つとしている。', explanation: '正しい。入契法は、入札契約の透明性・公正性の確保とあわせ、一括下請負の禁止徹底による適正な施工体制の確保を目的の一つとしている。' },
    ],
    correctKey: 'B',
    explanation: '入契法（公共工事の入札及び契約の適正化の促進に関する法律）は、公共工事の発注者に対し、毎年度の発注見通しの公表、入札及び契約に関する情報の公表、施工体制台帳の写しの提出要求、不正行為があった場合の建設業許可行政庁等への通知といった措置を法律上の義務として課している。発注見通しの公表は発注者の任意ではなく義務である。同法は、透明性の確保、公正な競争の促進、不正行為の排除の徹底、適正な施工の確保という4つの基本原則を掲げ、一括下請負の禁止の徹底も目的の一つとしている。\\n\\n【図解】入契法の基本原則と発注者の義務\\n　基本原則｜ねらい｜対応する主な措置\\n　透明性の確保｜手続を外部から見えるようにする｜発注見通しと契約情報の公表\\n　公正な競争の促進｜適正な価格での競争の実現｜入札参加資格の適切な設定\\n　不正行為の排除｜談合や一括下請負の防止｜許可行政庁等への通知\\n　適正な施工の確保｜品質と施工体制の確保｜施工体制台帳の写しの提出要求\\n　⇒ 発注見通しの公表は発注者に課された法律上の義務である\\n　⚠ 「発注見通しの公表は任意」とするのは義務規定を任意規定に読み替えた誤り。',
