    explanation: '建築基準法施行令に基づき、木造で高さ13メートルもしくは軒の高さ9メートルを超える建築物、または木造以外で階数が2以上の建築物の工事を行う場合、工事期間中は原則として工事現場の周囲に、地盤面から高さ1.8メートル以上の板塀その他これに類する仮囲いを設けなければならない。ただし、これと同等以上の効力を有する既存の塀がある場合や、周辺の状況により危害防止上支障がない場合はこの限りでない。仮囲いは通行人の安全確保と工事現場への立入防止を目的とするもので、工事完了後は撤去する。\\n\\n【図解】仮囲いの設置義務の要件\\n　建築物の種類｜設置義務が生じる規模｜仮囲いの高さ\\n　木造｜高さ13メートル超または軒高9メートル超｜1.8メートル以上\\n　木造以外｜階数が2以上｜1.8メートル以上\\n　⇒ 周囲の状況により危害防止上支障がない場合は省略できる\\n　⚠ 「木造には適用されない」「いかなる場合も省略できない」はいずれも誤り。',
