    explanation: '騒音規制法・振動規制法の規制基準値および作業時間帯の制限は、指定された規制地域の区域区分ごとに定められており、全国一律の基準ではない。区域は、良好な住居環境の保全が必要な地域や住居が集合する地域、学校・病院の周辺などを含む第1号区域と、それ以外の第2号区域に区分される。第1号区域では午後7時から翌午前7時までの作業が禁止され1日の作業時間は10時間以内、第2号区域では午後10時から翌午前6時までが禁止され1日14時間以内となる。市町村長は基準に適合しない作業に対して改善勧告や命令を行うことができる。\\n\\n【図解】第1号区域と第2号区域の規制の違い\\n　項目｜第1号区域｜第2号区域\\n　対象となる地域｜住居系や学校病院の周辺など｜それ以外の地域\\n　作業禁止時間帯｜午後7時から翌午前7時｜午後10時から翌午前6時\\n　1日の作業時間の上限｜10時間まで｜14時間まで\\n　⇒ 敷地境界線の基準値は騒音85デシベル、振動75デシベル\\n　⚠ 「規制基準値は区域区分にかかわらず全国一律」は区域制の趣旨に反し誤り。',
