    explanation: '労働基準法では、使用者が労働者を解雇しようとする場合、原則として少なくとも30日前に予告するか、予告に代えて30日分以上の平均賃金（解雇予告手当）を支払わなければならないと定められている（予告日数と平均賃金の支払日数を合算して30日以上とすることも可能）。また業務上の傷病による療養のための休業期間及びその後30日間は解雇が制限されるが、使用者が打切補償を支払う場合等、一定の例外もある。\n【図解】解雇予告制度の基本\n○原則30日前の予告又は30日分以上の解雇予告手当が必要\n○業務上傷病の療養期間中等は原則として解雇制限がある\n×予告・予告手当が一切不要、は重大な誤り\n→打切補償支払い等、解雇制限には例外規定もある\n⚠即時解雇には予告手当の支払いが必須★',
