    explanation: '建設リサイクル法は、コンクリート・アスファルト・コンクリート・木材等の特定建設資材について、一定規模以上の対象建設工事における分別解体及び再資源化等を促進することを目的とする法律である。受注者は工事着手前に発注者へ分別解体等の計画を説明する義務があり、発注者又は自主施工者は工事着手の一定日数前（原則7日前）までに都道府県知事等への届出が必要である。ただし、再資源化施設までの距離が一定以上離れている等の事情により、再資源化が著しく困難な場合には、縮減（焼却等による減量化）をもって足りるとする規定もあり、「常にすべての現場で完全な再資源化が可能」とするのは実態に即さない誤った記述である。\n【図解】建設リサイクル法の仕組み\n○特定建設資材の分別解体・再資源化等を促進する法律\n○受注者は着工前に発注者へ分別解体等の計画を説明\n○発注者・自主施工者は着工前（原則7日前）に届出が必要\n×常に完全な再資源化が可能、は実態に反する誤り\n⚠再資源化施設が遠隔の場合は縮減で足りる特例がある★',
