    correctKey: 'D',
    explanation: '労働基準法では、使用者は事業場の規模（労働者数）にかかわらず、各事業場ごとに労働者名簿及び賃金台帳を調製する義務を負う（就業規則の作成義務が常時10人以上の事業場に課されるのとは異なる）。労働者名簿には氏名・生年月日・履歴等、賃金台帳には賃金計算の基礎事項・賃金額等の法定記載事項を記入し、いずれも原則として5年間（当分の間3年間）保存しなければならない。「常時10人以上の事業場にのみ適用される」という記述は誤りである。\n【図解】労働者名簿・賃金台帳の調製義務\n○事業場規模にかかわらず調製義務がある（全事業場対象）\n○保存期間は原則5年間（当分の間3年間）\n×常時10人以上の事業場にのみ適用、は誤り\n→就業規則作成義務（常時10人以上）と混同しないこと\n⚠労働者数の多寡で調製義務の有無は変わらない★',
    difficulty: 'advanced',
