    correctKey: 'D',
    explanation: '大気汚染防止法及び石綿障害予防規則等に基づき、建築物等の解体・改修工事を行う場合は、石綿の使用の有無について事前調査を行い、その結果を記録・保存する必要がある。石綿の使用が確認された場合や、特定粉じん排出等作業に該当する場合は、作業開始前に都道府県知事等への届出、隔離養生・集じん排気装置の使用等の飛散防止措置が求められる。事前調査で石綿含有の有無が不明な場合は、分析調査を行うか、それが困難な場合は石綿含有建材とみなして飛散防止措置を講じる必要があり、「省略して石綿を含まないものとして扱ってよい」という記述は重大な誤りである。\n【図解】石綿事前調査と飛散防止\n○解体・改修前に石綿使用の有無を事前調査し記録保存\n○該当作業は都道府県知事等への事前届出が必要な場合がある\n×不明な場合は石綿非含有として扱ってよい、は重大な誤り\n→隔離養生・集じん排気装置等の飛散防止措置が必要\n⚠石綿ばく露は重篤な健康被害（中皮腫等）を招く★',
