    explanation: '建設業法に基づく技術検定制度は、施工技術の向上を図ることを目的とし、第一次検定（学科試験に相当）及び第二次検定（実地試験に相当）により実施され、第一次検定合格者には技士補、第二次検定合格者には技士の称号が付与される。技術検定制度の見直しにより、一定年齢（19歳以上等）であれば実務経験を問わず第一次検定を受検できる区分が設けられている。1級施工管理技士は監理技術者・主任技術者として、2級施工管理技士は主任技術者として配置できる工事の規模等に差異がある。\n【図解】技術検定制度の仕組み\n○第一次検定（学科相当）・第二次検定（実地相当）の2段階\n○合格者には技士補（第一次）・技士（第二次）の称号\n×学生の受検が一切不可、1級2級に差異なし、は誤り\n→1級は監理技術者・主任技術者、2級は主任技術者として配置\n⚠1級施工管理技士は専任技術者要件も満たす代表的資格★',
